853	std::optional<AgentError> ProviderAgent::gateway_answer(const std::string& code, const std::string& body) const
854	{
855	    const std::string& name = m_config.profile.display_name;
856	    if (code == "unauthorized")
857	        return AgentError{"invalid_credentials", sign_in_ended(), false};
858	    if (code == "credits_exhausted") {
859	        // What the message costs and what the person has, from the gateway's
860	        // numbers, in the app's language. The gateway always sends both.
861	        const json answer = json::parse(body, nullptr, false);
862	        if (!answer.is_object() || !answer.value("cost", json()).is_number_unsigned() || !answer.value("balance", json()).is_number_unsigned())
863	            return std::nullopt;
864	        const unsigned cost = answer["cost"].get<unsigned>();
865	        // TRN %1% is what the message costs in credits, %2% the credits the person has.
866	        return AgentError{"credits_exhausted",
867	                          Slic3r::format(translated_plural("This message needs %1% credit; you have %2%.",
868	                                                           "This message needs %1% credits; you have %2%.", cost),
869	                                         cost, answer["balance"].get<unsigned>()),
870	                          false};
871	    }
872	    // The person sent too many turns in a minute.
873	    if (code == "rate_limited")
874	        return rate_limited(name);
875	    if (code == "request_too_large")
876	        return too_large(name);
877	    return std::nullopt;
878	}
