881	{
882	    const std::string& name = m_config.profile.display_name;
883	    const ServiceSays  says = service_says(answer);
884	    if (out_of_credits(status, says))
885	        return provider_out_of_credits(name);
886	    // Anthropic's 403 is a key without permission for what it asked; OpenAI's
887	    // and OpenRouter's 403s name other causes (a country, moderation, a key's
888	    // spending limit).
889	    if (status == 401 || (status == 403 && says.type == "permission_error"))
890	        // TRN %1% is an AI provider, such as OpenAI.
891	        return AgentError{"invalid_credentials", Slic3r::format(translated(L("The %1% API key was rejected. Update the AI configuration and try again.")), name), false};
892	    if (too_long(status, says))
893	        return too_large(name);
894	    if (status == 429)
895	        return rate_limited(name);
896	    return std::nullopt;
897	}
